var sortIndirectArgsCS = `
fn writeSortIndirectArgs(
	buf: ptr<storage, array<u32>, read_write>,
	baseSlot: u32,
	count: u32,
	slotInfo: vec4<u32>
) {
	let n = slotInfo.x;
	if (n >= 1u) {
		let g = slotInfo.y;
		let wc = (count + g - 1u) / g;
		let off = baseSlot * 3u;
		(*buf)[off + 0u] = wc;
		(*buf)[off + 1u] = 1u;
		(*buf)[off + 2u] = 1u;
	}
	if (n >= 2u) {
		let g = slotInfo.z;
		let wc = (count + g - 1u) / g;
		let off = (baseSlot + 1u) * 3u;
		(*buf)[off + 0u] = wc;
		(*buf)[off + 1u] = 1u;
		(*buf)[off + 2u] = 1u;
	}
	if (n >= 3u) {
		let g = slotInfo.w;
		let wc = (count + g - 1u) / g;
		let off = (baseSlot + 2u) * 3u;
		(*buf)[off + 0u] = wc;
		(*buf)[off + 1u] = 1u;
		(*buf)[off + 2u] = 1u;
	}
}
`;

export { sortIndirectArgsCS as default };
